import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    middle = close.rolling(18).mean()
    width = 2.5 * close.rolling(18).std(ddof=0)
    mid = middle.to_numpy()
    upper = (middle + width).to_numpy()
    lower = (middle - width).to_numpy()
    c = close.to_numpy()

    pos = np.zeros(len(df), dtype=int)
    state = 0
    for t in range(len(df)):
        if np.isnan(mid[t]):
            state = 0
        elif state == 0:
            if c[t] > upper[t]:
                state = 1
            elif c[t] < lower[t]:
                state = -1
        elif state == 1:
            if c[t] <= mid[t]:
                state = 0
        elif state == -1:
            if c[t] >= mid[t]:
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)

