import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    c = close.to_numpy()
    sma = close.rolling(12).mean().to_numpy()
    prev_c = np.roll(c, 1)
    prev_sma = np.roll(sma, 1)
    prev_sma[0] = np.nan

    pos = np.zeros(len(c), dtype=int)
    state = 0
    extreme = 0.0
    for t in range(len(c)):
        if state == 0:
            if not np.isnan(prev_sma[t]) and c[t] > sma[t] and prev_c[t] <= prev_sma[t]:
                state, extreme = 1, c[t]
            elif not np.isnan(prev_sma[t]) and c[t] < sma[t] and prev_c[t] >= prev_sma[t]:
                state, extreme = -1, c[t]
        elif state == 1:
            extreme = max(extreme, c[t])
            if c[t] < extreme * (1 - 0.05):
                state = 0
        elif state == -1:
            extreme = min(extreme, c[t])
            if c[t] > extreme * (1 + 0.05):
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)

